import{_ as a,o as t,c as n,a5 as s}from"./chunks/framework.Bqo7-qSd.js";const u=JSON.parse('{"title":"Subroutine Calls (call / return)","description":"","frontmatter":{"title":"Subroutine Calls (call / return)","order":9},"headers":[],"relativePath":"en/latest/tutorial/script/call-and-return.md","filePath":"en/latest/tutorial/script/call-and-return.md","lastUpdated":1795484315000}'),l={name:"en/latest/tutorial/script/call-and-return.md"};function r(c,e,i,o,d,p){return t(),n("div",null,[...e[0]||(e[0]=[s(`<h1 id="subroutine-calls-call-return" tabindex="-1">Subroutine Calls (call / return) <a class="header-anchor" href="#subroutine-calls-call-return" aria-label="Permalink to &quot;Subroutine Calls (call / return)&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p><code>call</code> runs a <code>branch</code> in the current script as a subroutine: control enters the branch and returns to the statement after the <code>call</code> when it reaches <code>return</code>.</p><ul><li>Unlike <code>jump_branch</code>, a <code>call</code> remembers its return address on a call stack.</li><li>Unlike <code>jump</code>, a <code>call</code> stays inside the same shot. <code>jump</code> switches shots and discards pending call frames; cross-script calls are not supported yet.</li><li>The call stack is runtime state: it is saved, restored, and rolled back together with the rest of the execution state.</li><li>Recursive calls (direct or indirect) are rejected at compile time, and the call chain is capped at 256 levels.</li><li><code>return</code> with an empty call stack behaves like <code>end</code>: it finishes the current shot.</li></ul><h2 id="syntax" tabindex="-1">Syntax <a class="header-anchor" href="#syntax" aria-label="Permalink to &quot;Syntax&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>call &lt;branch_name&gt;</span></span>
<span class="line"><span>return</span></span></code></pre></div><h2 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to &quot;Parameters&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Parameter</th><th>Required</th><th>Example</th><th>Description</th></tr></thead><tbody><tr><td>branch_name</td><td>Yes</td><td><code>gift_scene</code></td><td>A branch declared in the current script</td></tr></tbody></table><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>call gift_scene</span></span>
<span class="line"><span>Kona &quot;Back at the call site.&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>branch gift_scene</span></span>
<span class="line"><span>	Kona &quot;This is a shared scene.&quot;</span></span>
<span class="line"><span>	return</span></span></code></pre></div><p>Nested calls:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>call chapter_intro</span></span>
<span class="line"><span></span></span>
<span class="line"><span>branch chapter_intro</span></span>
<span class="line"><span>	Kona &quot;The chapter starts.&quot;</span></span>
<span class="line"><span>	call phone_ring</span></span>
<span class="line"><span>	Kona &quot;The chapter ends.&quot;</span></span>
<span class="line"><span>	return</span></span>
<span class="line"><span></span></span>
<span class="line"><span>branch phone_ring</span></span>
<span class="line"><span>	Kona &quot;The phone rings.&quot;</span></span>
<span class="line"><span>	return</span></span></code></pre></div><h2 id="how-a-called-branch-ends" tabindex="-1">How a called branch ends <a class="header-anchor" href="#how-a-called-branch-ends" aria-label="Permalink to &quot;How a called branch ends&quot;">​</a></h2><ul><li>An explicit <code>return</code> is the clearest option: control goes back to the call site.</li><li>Falling off the end of a branch connects to the compiler-generated <code>halt</code>, which finishes the whole shot. <strong>Prefer an explicit <code>return</code> in every called branch.</strong></li></ul><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ol><li>The target must be a branch in the current script; use <code>jump</code> for another script.</li><li>Recursive calls (including mutual recursion) fail to compile.</li><li><code>jump</code> discards pending call frames; do not rely on <code>return</code> across shots.</li><li><code>call</code> and <code>return</code> work inside choices, branches, and conditional blocks.</li><li>The runtime failure panel offers retry/stop for <code>call</code>, never skip: skipping would enter a branch without a return frame.</li></ol>`,16)])])}const b=a(l,[["render",r]]);export{u as __pageData,b as default};
